// LifePass translation layer: a port of the iOS LPStrings (Localization.swift).
//
// Language follows the member's ACCOUNT preference (profiles.locale), not the
// device, so a tourist with an English phone can still read LifePass in
// Icelandic and vice versa. Before any account language is known (onboarding,
// sign-in, sign-up) the device language decides, reduced to the two the app
// speaks. F3 keeps `currentLanguage` in step with the account.
//
// The words come from two places (./tables.ts):
// - the iOS dictionaries, generated by scripts/import-ios-strings.py into
//   strings.{en,is}.json; never retype iOS copy by hand, regenerate it;
// - each package's Android-only pack, src/i18n/android/<package-id>.ts.
//
//   t('tab.home')                         // "Home" / "Heim"
//   t('checkin.credits_left', { count })  // "{count} credits remaining"
//   tp('account.pass_visits_left', 21)    // Icelandic singular for 21
//
import { getLocales } from 'expo-localization';
import { useMemo } from 'react';
import { create } from 'zustand';

import { tables, type Lang } from './tables';

export type { Conflict, GeneratedKey, Lang, Table } from './tables';

/** The phone's own language, reduced to the two the app speaks. */
export function deviceLanguage(): Lang {
  const first = getLocales()[0]?.languageCode ?? '';
  return first.startsWith('is') ? 'is' : 'en';
}

/** Any language code, reduced to the two the app speaks ('is…' or English). */
export function normaliseLang(value: string | null | undefined): Lang {
  return value?.toLowerCase().startsWith('is') ? 'is' : 'en';
}

type LanguageState = { language: Lang; setLanguage: (lang: Lang) => void };

/** The language on screen right now. React code subscribes with `useT()`. */
export const useLanguageStore = create<LanguageState>((set) => ({
  language: deviceLanguage(),
  setLanguage: (language) => set({ language }),
}));

/**
 * The language on screen, for text built where there is no React tree to ask
 * (the API error model, notification content, background work): iOS's
 * `LPStrings.currentLanguage`.
 */
export function currentLanguage(): Lang {
  return useLanguageStore.getState().language;
}

export function setCurrentLanguage(lang: Lang): void {
  if (useLanguageStore.getState().language !== lang) {
    useLanguageStore.getState().setLanguage(lang);
  }
}

export type Params = Readonly<Record<string, string | number>>;

/**
 * Look up a key: is → en → the key itself, so a cell is never blank (an
 * empty Icelandic value counts as missing). Any language other than
 * Icelandic reads English, as iOS's `LPLang(rawValue:) ?? .en` does.
 */
export function lookup(key: string, lang: Lang): string {
  if (lang === 'is') {
    const translated = tables.is[key];
    if (translated) return translated;
  }
  return tables.en[key] ?? key;
}

/** True when either table has the key (a key that would not render as itself). */
export function hasKey(key: string): boolean {
  return key in tables.en || key in tables.is;
}

/** Replace every `{name}` with its value. */
export function fill(template: string, params?: Params): string {
  if (!params) return template;
  let result = template;
  for (const [name, value] of Object.entries(params)) {
    result = result.split(`{${name}}`).join(String(value));
  }
  return result;
}

/**
 * `.one` or `.many` for a count.
 *
 * English is simple: only 1 is singular. Icelandic is not: it takes the
 * singular for 1, 21, 31, 101 … but NOT for 11 (and not for 111 either).
 * Writing `count === 1 ? one : many` produces "21 máltíðir" where a person
 * would say "21 máltíð", which is why every Icelandic `.one` value keeps its
 * `{count}` placeholder: the number there is often not 1. Any other language
 * takes the English rule.
 */
export function pluralKey(base: string, count: number, lang: Lang): string {
  let singular: boolean;
  if (lang === 'is') {
    const magnitude = Math.abs(Math.trunc(count));
    singular = magnitude % 10 === 1 && magnitude % 100 !== 11;
  } else {
    singular = count === 1;
  }
  return `${base}.${singular ? 'one' : 'many'}`;
}

/** Translate in an explicit language. */
export function translate(key: string, lang: Lang, params?: Params): string {
  return fill(lookup(key, lang), params);
}

/** Plural-aware translate in an explicit language; `{count}` is filled automatically. */
export function translatePlural(base: string, count: number, lang: Lang, params?: Params): string {
  return translate(pluralKey(base, count, lang), lang, { count, ...params });
}

/** Translate in the current language (for code outside React). */
export function t(key: string, params?: Params): string {
  return translate(key, currentLanguage(), params);
}

/** Plural-aware translate in the current language; `{count}` is filled automatically. */
export function tp(base: string, count: number, params?: Params): string {
  return translatePlural(base, count, currentLanguage(), params);
}

export type Translator = {
  readonly language: Lang;
  readonly t: (key: string, params?: Params) => string;
  readonly tp: (base: string, count: number, params?: Params) => string;
};

/**
 * Hook: the current language and `t`/`tp` bound to it. Re-renders when the
 * language changes; the functions keep their identity until then, so they
 * are safe in dependency lists.
 */
export function useT(): Translator {
  const language = useLanguageStore((s) => s.language);
  return useMemo(
    () => ({
      language,
      t: (key: string, params?: Params) => translate(key, language, params),
      tp: (base: string, count: number, params?: Params) => translatePlural(base, count, language, params),
    }),
    [language],
  );
}
